#[verus::spec]
fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Ensure that the input array is not modified
    let n = a.len();
    let (left, right) = if n == 0 {
        // If the input array is empty, return two empty arrays
        (Vec::new(), Vec::new())
    } else if n == 1 {
        // If the input array has one element, return one empty array and the original array
        (Vec::new(), a.clone())
    } else {
        // Split the array into two non-empty parts
        let mid = n / 2; // Choose a midpoint for splitting
        let left = a[0..mid].to_vec(); // First half
        let right = a[mid..n].to_vec(); // Second half
        (left, right)
    };

    // Verus specifications
    // Requires: The input array can be of any length
    // Ensures: The concatenation of the two returned arrays equals the original array
    // Ensures: The sum of the lengths of the two returned arrays equals the length of the original array
    // Ensures: If the original array has length greater than 1, each returned array is strictly shorter than the original array
    assert!(left.len() + right.len() == n);
    assert!(left.len() < n || right.len() < n); // At least one must be shorter if n > 1
    assert!(left.iter().chain(right.iter()).cloned().collect::<Vec<i32>>() == a);

    (left, right)
}